public class UseBaseMinion : SkillState
{
	public GameObject minionPrefab;

	public List<BasicMinion> minionList = new List<BasicMinion>();

	public BasicMinion currentMinion;

	public SyncedNumVarStat maxSummonStat = new SyncedNumVarStat(3f);

	public int summonCount = 1;

	public int currentCount;

	public Vector2 spawnLocation;

	public Vector2 spawnOffset;

	public float summonDuration;

	public int summonHealth;

	public override string OnEnterAnimStr => parent.PBAoEAnimStr;

	public UseBaseMinion(string newName, FSM newFSM, Player newPlayer)
		: base(newName, newFSM, newPlayer)
	{
		isSummonSkill = true;
		SetAnimTimes(0.1f, 0.2f, 0.3f, 0.8f, 0.9f);
	}

	public override void OnEnter()
	{
		base.OnEnter();
		parent.odPauseStopwatch.IsRunning = true;
	}

	public override void ExecuteSkill()
	{
		base.ExecuteSkill();
		summonCount = skillData.GetValue<int>(StatData.spawnStr);
		summonDuration = skillData.GetValue<float>(StatData.durStr);
		summonHealth = skillData.GetValue<int>(StatData.healthStr);
		spawnLocation = parent.transform.position;
		SummonAllMinions();
		CameraController.ShakeCamera(0.25f);
	}

	public virtual void LimitToMaxMinions()
	{
		if ((float)minionList.Count > maxSummonStat.CurrentValue && minionList[0] != null)
		{
			minionList[0].DestroyMinion();
			minionList.RemoveAt(0);
		}
	}

	public virtual void SummonAllMinions()
	{
		minionList.RemoveNullValues();
		parent.CleanUpPlayerSummonsList();
		for (currentCount = 0; currentCount < summonCount; currentCount++)
		{
			SummonMinion();
			LimitToMaxMinions();
		}
	}

	public virtual BasicMinion SummonMinion()
	{
		currentMinion = ChaosInst<BasicMinion>(minionPrefab, GetSpawnLocation());
		currentMinion.gameObject.name = minionPrefab.name + parent.skillCategory;
		currentMinion.parentTrans = parent.transform;
		currentMinion.parentSummonList = parent.playerSummonsList;
		currentMinion.SetSkillInfo(parent.skillCategory, skillID, currentLevel, isUltimate);
		currentMinion.summonDuration = summonDuration;
		currentMinion.startingHealth = summonHealth;
		currentMinion.isEmpowered = IsEmpowered;
		if (Inventory.EitherPlayerHasItem(FlatDamage.staticID) && FlatDamage.damageMod != null)
		{
			currentMinion.health.damageTakenStat.Modify(FlatDamage.damageMod, addMod: true);
		}
		minionList.Add(currentMinion);
		parent.playerSummonsList.Add(currentMinion.gameObject);
		return currentMinion;
	}

	public virtual Vector2 GetSpawnLocation()
	{
		spawnOffset = Entity.GetAvailableNearbyLocation(spawnLocation + Globals.GetRotatedCircleVector(summonCount, currentCount, inputVector), excludeOrigin: false, randomize: false);
		return (!(spawnOffset == Vector2.zero)) ? spawnOffset : spawnLocation;
	}
}

