			CameraController.ShakeCamera(0.25f);
		}
		return attackStarted;
	}

	public override void HandleHoldButton()
	{
		if (parent.anim.AnimPlayed(cancelThreshold))
		{
			parent.FaceTarget(targetVector + (Vector2)parent.transform.position);
			parent.anim.PlayDirectional(OnEnterAnimStr, -1, cancelThreshold);
		}
		base.HandleHoldButton();
	}

	public override void FixedUpdate()
	{
		if (StartAttack() && !skillExecuted)
		{
			UpdateTargetVector();
			UpdateBeamVector();
		}
	}

	public override void OnExit()
	{
		base.OnExit();
		if (currentBeam != null)
		{
			currentBeam.StopBeam();
		}
	}

	public virtual void UpdateTargetVector()
	{
		inputVector = GetInputVector(faceInputVector: false, useAimVector: true, ignoreZero: false);
