		public new static string staticID = "StalwartDefenders";

		private static Vector2[] moveVectors = new Vector2[4]
		{
			new Vector2(-1.5f, 3f),
			new Vector2(-3f, 1.5f),
			new Vector2(3f, 1.5f),
			new Vector2(1.5f, 3f)
		};

		private static float movementUnit = 1.5f;

		private static float[] delayTimes = new float[4] { 0.1875f, 0.0625f, 0.25f, 0.125f };

		private static Color altColor = new Color(0.5f, 0.5f, 0.5f, 1f);

		private ChessPiece currentCP;

		private Vector2 spawnCenter;

		private Vector2 perpendVec;

		public override string OnEnterAnimStr => parent.GSlamAnimStr;

		public UseChessPiece(FSM parentFSM, Player parentEntity)
			: base(staticID, parentFSM, parentEntity)
		{
			SetAnimTimes(0.1f, 0.2f, 0.3f, 0.8f, 0.9f);
		}

		public override void OnEnter()
		{
			base.OnEnter();
			parent.movement.EndMovement();
			inputVector = Entity.GetFacingDirectionVector(parent.facingDirection);
			spawnCenter = Globals.GetSafeLinecastVector(parent.transform.position, inputVector, movementUnit, ChaosCollisions.layerAllWallAndObst);
			perpendVec = Globals.GetPerpendicular(inputVector) * movementUnit;
		}

		public override void ExecuteSkill()
		{
			base.ExecuteSkill();
			spawnCenter -= perpendVec * 1.5f;
			for (int i = 0; i < 4; i++)
			{
				CreateChessPiece(GetChessVars(parent.facingDirection, i), delayTimes[i]);
			}
			DustEmitter poolItem = PoolManager.GetPoolItem<DustEmitter>();
			int particleCount = 100;
			float scale = 0.25f;
			Vector3? emitPosition = parent.transform.position;
			poolItem.EmitCircle(particleCount, scale, -1f, -1f, emitPosition);
			SoundManager.PlayAudioWithDistance("ChessPiece", spawnCenter);
			SoundManager.PlayAudioWithDistance("RockForm", spawnCenter);
		}

		private void CreateChessPiece(ChessPieceVars givenVars, float givenDelay)
		{
			if (Globals.CheckCircle(givenVars.spawnVector, 0.125f, ChaosCollisions.layerAll))
			{
				currentCP = ChaosInst<ChessPiece>(ChessPiece.Prefab, givenVars.spawnVector);
				currentCP.landingPosition = givenVars.endVector;
				currentCP.skillCategory = parent.skillCategory;
				currentCP.attack.SetAttackInfo(parent.skillCategory, skillID);
				currentCP.attack.knockbackOverwriteVector = inputVector;
				currentCP.startRight = givenVars.startRight;
				currentCP.endRight = givenVars.endRight;
				currentCP.spawnDelay = givenDelay;
				if (givenVars.changeColor)
				{
					currentCP.spriteRenderer.color = altColor;
				}
				currentCP.isEmpowered = IsEmpowered;
			}
		}

		private ChessPieceVars GetChessVars(FacingDirection givenDir, int givenIndex)
		{
			ChessPieceVars result = new ChessPieceVars
			{
				spawnVector = spawnCenter + perpendVec * givenIndex,
				endVector = Vector2.zero
			};
			switch (givenDir)
			{
			case FacingDirection.Up:
				result.endVector = moveVectors[givenIndex];
				result.startRight = givenIndex < 2;
				result.endRight = !result.startRight;
				break;
			case FacingDirection.Down:
				result.endVector = -moveVectors[givenIndex];
				result.startRight = givenIndex >= 2;
				result.endRight = !result.startRight;
				break;
			case FacingDirection.Left:
				result.endVector = Globals.GetPerpendicular(moveVectors[givenIndex]);
				result.startRight = false;
				result.endRight = false;
				break;
			case FacingDirection.Right:
				result.endVector = Globals.GetPerpendicular(moveVectors[givenIndex], horizontal: false);
				result.startRight = true;
				result.endRight = true;
				break;
			}
			result.changeColor = givenIndex < 2;
			result.endVector += result.spawnVector;
			return result;
		}
	}

