public class Rogue : Enemy
{
	public class RogueAttackState : AttackStateRotational
	{
		private bool queueDoubleAttack;

		private bool doubleAttack;

		private bool alwaysDouble;

		private bool attackHit;

		private float calcExitTime;

		public new Rogue parent;

		public RogueAttackState(string newName, FSM newFSM, Rogue newEnt)
			: base(newName, newFSM, newEnt)
		{
			parent = newEnt;
			alwaysDouble = parent.CurrentDifficulty >= 2;
			Attack attack = parent.attack;
			attack.attackCollisionEventHandlers = (Attack.AttackCollisionEventHandler)Delegate.Combine(attack.attackCollisionEventHandlers, new Attack.AttackCollisionEventHandler(OnAttackHit));
		}

		public override void OnEnter()
		{
			doubleAttack = queueDoubleAttack;
			queueDoubleAttack = parent.IsStealthed || (alwaysDouble && !doubleAttack);
			parent.attack.SetAttackInfo(parent.skillCategory, parent.attackSkillID, (!queueDoubleAttack) ? 1 : 2);
			parent.FaceTarget(parent.closestTargetInfo.position, parent.animFacingDirections);
			parent.anim.Play("Attack", -1, (!queueDoubleAttack) ? 0.25f : 0.4f);
			if (parent.closestTargetInfo.hurtBoxTransform != null)
			{
				parent.attack.transform.localEulerAngles = Globals.GetRotationVector((parent.closestTargetInfo.hurtBoxTransform.position - parent.hurtBoxTransform.position).normalized) * ((!parent.isFacingRight) ? (-1f) : 1f);
			}
			parent.movement.EndMovement();
			soundPlayed = false;
			calcExitTime = 1.25f;
		}

		public override void Update()
		{
			if (parent.attackAudioID != string.Empty && !soundPlayed && parent.anim.AnimPlayed(parent.attackAnimAudioPlayTime))
			{
				soundPlayed = true;
				string attackAudioID = parent.attackAudioID;
				Vector2? soundOrigin = parent.transform.position;
				float overridePitch = UnityEngine.Random.Range(parent.minPitch, parent.maxPitch);
				SoundManager.PlayAudioWithDistance(attackAudioID, soundOrigin, null, 24f, -1f, overridePitch);
			}
			if (queueDoubleAttack && parent.anim.AnimPlayed(0.6f))
			{
				fsm.ChangeState("Attack", allowSelfTransition: true);
			}
			else if (parent.anim.AnimPlayed(calcExitTime))
			{
				ExitTransition();
			}
		}

		public override void OnExit()
		{
			base.OnExit();
			doubleAttack = false;
		}

		private void OnAttackHit(Collider2D col)
		{
			if (doubleAttack)
			{
				calcExitTime = 2f;
			}
		}
	}

	public class RogueHurtState : EnemyHurtState
	{
		public new Rogue parent;

		public RogueHurtState(string newName, FSM newFSM, Rogue newEnt)
			: base(newName, newFSM, newEnt)
		{
			parent = newEnt;
		}

		public override void OnEnter()
		{
			if (parent.stealthState != null && parent.IsStealthed)
			{
				parent.stealthState.EndStealth();
			}
			if (parent.CanUseSkills && parent.teleportState != null && parent.teleportState.IsReady() && Vector2.Distance(parent.closestTargetInfo.position, parent.transform.position) >= parent.teleportState.minActivationRadius)
			{
				fsm.ChangeState(parent.teleportState.name);
			}
			else
			{
				base.OnEnter();
			}
		}
	}

	public class RogueStealthState : StealthState
	{
		public new Rogue parent;

		public RogueStealthState(string newName, FSM newFSM, Rogue newEnt, int newReq, int newPriority, float newMin, float newMax, float newCD, bool newAuto = true)
			: base(newName, newFSM, newEnt, newReq, newPriority, newMin, newMax, newCD, newAuto)
		{
			parent = newEnt;
			requireLineOfSight = false;
		}

		public override bool IsReady()
		{
			return !parent.IsStealthed && base.IsReady();
		}

		public override void OnEnter()
		{
			if (parent.IsStealthed)
			{
				StartCooldown();
				ExitTransition();
			}
			else
			{
				base.OnEnter();
				SoundManager.PlayAudioWithDistance("RogueStealth", parent.transform.position);
			}
		}
	}

	public class RogueTeleportState : RandomTeleportState
	{
		public new Rogue parent;

		public RogueTeleportState(string newName, FSM newFSM, Rogue newEnt, int newReq, int newPriority, float newMin, float newMax, float newCD, bool newAuto = true)
			: base(newName, newFSM, newEnt, newReq, newPriority, newMin, newMax, newCD, newAuto)
		{
			parent = newEnt;
			exitTime = 0f;
			spawnInitialPortal = false;
		}

		public override void OnEnter()
		{
			Enemy.PlayTeleportSmokeEffect(parent.transform.position);
			base.OnEnter();
		}

		public override void ExitTransition()
		{
			if (parent.UpdateTargetInfo() != null)
			{
				fsm.ChangeState("Lunge");
			}
		}
	}

	public class RogueLungeState : LungeState
	{
		public new Rogue parent;

		public RogueLungeState(string newName, FSM newFSM, Rogue newEnt, int newReq, int newPriority, float newMin, float newMax, float newCD, bool newAuto = true)
			: base(newName, newFSM, newEnt, newReq, newPriority, newMin, newMax, newCD, newAuto)
		{
			parent = newEnt;
			Attack attack = parent.attack;
			attack.attackCollisionEventHandlers = (Attack.AttackCollisionEventHandler)Delegate.Remove(attack.attackCollisionEventHandlers, new Attack.AttackCollisionEventHandler(StopLunge));
			Attack attack2 = parent.attack;
			attack2.attackCollisionEventHandlers = (Attack.AttackCollisionEventHandler)Delegate.Combine(attack2.attackCollisionEventHandlers, new Attack.AttackCollisionEventHandler(StopLunge));
			castingAnimName = "Charging";
			attackSkillID = "NeutralRogueLunge";
			windupTime = 0.625f;
			attackAnimActiveTime = 0.5f;
			dashSpeed = 40f;
			dashDuration = 0.125f;
			rotationalAttackAnim = true;
		}

		public override void OnLungeComplete()
		{
			base.OnLungeComplete();
			if (parent.stealthState != null)
			{
				parent.stealthState.EndStealth();
			}
		}

		public void StopLunge(Collider2D col)
		{
			OnLungeComplete();
			parent.movement.EndMovement();
		}

