import yaml,re,sys
D="C:/visual projects/reverse-kit/pipeline/_work/run_wol2/records/collections/"
ids=set()
for p in ['08','09','10']:
    d=yaml.safe_load(open(f"bak/c-fsm_catalogs.part{p}.yaml",encoding='utf8'))
    for c in d['candidates']:
        ids.add(c['type'].split('.')[-1])
        for x in c.get('calls',[]): ids.add(x)
        for f in c.get('data_fields',[]): ids.add(f['name'])
ids={i for i in ids if len(i)>4}
for p in ['08','09','10','11']:
    t=open(D+f"c-fsm_catalogs.part{p}.yaml",encoding='utf8').read()
    d=yaml.safe_load(t)
    pub=[]
    for sec in ('catalog','rules'):
        for r in d.get(sec,[]):
            for k in ('own_name','title','behavior','conditions'):
                v=r.get(k)
                if v: pub.append((r['id'],k,v if isinstance(v,str) else ' '.join(v)))
    for k in ('goal','open_questions','acceptance'):
        v=d.get(k); pub.append(('-',k,v if isinstance(v,str) else ' '.join(v)))
    for i,k,v in pub:
        for w in re.findall(r'[A-Za-z_][A-Za-z0-9_]{3,}',v):
            if w in ids or re.search(r'\.(cs|json|csv|prefab)$',w): print(p,i,k,w)
        for m in re.findall(r'\b\w+\.(?:json|cs|csv|prefab)\b',v): print(p,i,k,m)
EOF
